package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser#nextToken.
 * Designed to maximize branch and line coverage.
 */
public class ReaderBasedJsonParser_nextToken_TriageGen2Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactory();
    }

    @Test
    public void testNextToken_EndOfString() throws IOException {
        String json = "null";
        JsonParser parser = factory.createParser(new StringReader(json));
        assertEquals(JsonToken.VALUE_NULL, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_BooleanTrue() throws IOException {
        String json = "true";
        JsonParser parser = factory.createParser(new StringReader(json));
        assertEquals(JsonToken.VALUE_TRUE, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_BooleanFalse() throws IOException {
        String json = "false";
        JsonParser parser = factory.createParser(new StringReader(json));
        assertEquals(JsonToken.VALUE_FALSE, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_PositiveNumber() throws IOException {
        String json = "123";
        JsonParser parser = factory.createParser(new StringReader(json));
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_NegativeNumber() throws IOException {
        String json = "-123";
        JsonParser parser = factory.createParser(new StringReader(json));
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_String() throws IOException {
        String json = "\"hello\"";
        JsonParser parser = factory.createParser(new StringReader(json));
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_ObjectStructure() throws IOException {
        String json = "{\"key\":\"value\"}";
        JsonParser parser = factory.createParser(new StringReader(json));

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals("key", parser.getCurrentName());

        // This triggers the logic: if (_currToken == JsonToken.FIELD_NAME) return _nextAfterName();
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_ArrayStructure() throws IOException {
        String json = "[1, 2]";
        JsonParser parser = factory.createParser(new StringReader(json));

        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_NestedContexts() throws IOException {
        String json = "{\"a\": [1]}";
        JsonParser parser = factory.createParser(new StringReader(json));

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertNull(parser.nextToken());
    }

    @Test(expected = IOException.class)
    public void testNextToken_MismatchedEndArray() throws IOException {
        String json = "]}"; // Trying to close array that isn't open
        JsonParser parser = factory.createParser(new StringReader(json));
        parser.nextToken();
    }

    @Test(expected = IOException.class)
    public void testNextToken_MismatchedEndObject() throws IOException {
        String json = "]}"; // Trying to close object context with bracket
        // We trigger the context mismatch by starting with a non-object/array
        String json2 = "1]}"; 
        JsonParser parser = factory.createParser(new StringReader(json2));
        parser.nextToken(); // 1
        parser.nextToken(); // This should trigger mismatch if the parser thinks it's in a scope
    }

    @Test(expected = IOException.class)
    public void testNextToken_UnexpectedValueCloser() throws IOException {
        // Testing the case where ']' or '}' is encountered where a value is expected
        String json = "[ ]"; 
        // In a standard array, ']' is a valid token. 
        // To hit the "reportUnexpectedChar" in the switch, we need a context where 
        // i == ']' but it wasn't caught by the "Closing scope?" block.
        // This usually happens if the parser state is corrupted or manually manipulated,
        // but we can simulate a bad sequence.
        String badJson = "{\"a\": }"; 
        JsonParser parser = factory.createParser(new StringReader(badJson));
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME
        parser.nextToken(); // Should hit the '}' case in switch
    }

    @Test
    public void testNextToken_EmptyInput() throws IOException {
        String json = "";
        JsonParser parser = factory.createParser(new StringReader(json));
        assertNull(parser.nextToken());
    }

    @Test
    public void testNextToken_WhitespaceHandling() throws IOException {
        String json = "   {   \"a\"   :   123   }   ";
        JsonParser parser = factory.createParser(new StringReader(json));
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.FIELD_NAME, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }

    @Test
    public void testNextToken_IncompleteTokenCleanup() throws IOException {
        // Tests the _tokenIncomplete and _skipString logic
        // Note: Hard to trigger _tokenIncomplete naturally without custom implementation,
        // but we can test the branch via a sequence that implies incomplete processing.
        String json = "{\"a\": \"\"}";
        JsonParser parser = factory.createParser(new StringReader(json));
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME
        assertEquals(JsonToken.VALUE_STRING, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
    }
}
